import json
import os
import urllib.parse
import urllib.request

BASE = os.environ.get("PRICING_URL", "http://prices.internal/api/v2/price")


def get_price(sku: str) -> float:
    url = f"{BASE.rstrip('/')}/{urllib.parse.quote(sku, safe='')}"
    request = urllib.request.Request(url)
    if key := os.environ.get("PRICING_API_KEY"):
        request.add_header("X-Pricing-Key", key)
    with urllib.request.urlopen(request, timeout=5) as response:
        return float(json.load(response)["price"])


def get_total(skus: list[str]) -> float:
    return sum(map(get_price, skus), 0.0)
